-- ============================================
-- FIX — notation vectorielle (fleche au-dessus, pas devant)
-- A coller dans : Supabase > SQL Editor > New query
-- ============================================
-- Le cours "Vecteurs : l'essentiel" avait ete seede avec la notation
-- "→AB" (fleche devant les lettres), qui n'est pas celle enseignee en
-- classe (fleche au-dessus des deux lettres : AB avec un vecteur dessus).
-- Ce script remplace le contenu par la version correcte, qui utilise
-- $\overrightarrow{AB}$ (rendu par KaTeX avec la fleche au-dessus, comme
-- au tableau). S'applique a toutes les lignes correspondantes, meme s'il
-- en reste plusieurs en double avant que supabase-dedupe-cours.sql soit
-- passe.

UPDATE cours
SET contenu = $coursJson4$[{"id": 1, "type": "texte", "content": "Un vecteur est un déplacement. $\\overrightarrow{AB}$, c'est aller de A à B. Trois informations : direction, sens, longueur."}, {"id": 2, "type": "definition", "content": "Deux vecteurs sont égaux s'ils ont la même direction, le même sens et la même longueur — peu importe où on les dessine.", "titre": "Deux vecteurs égaux"}, {"id": 3, "type": "definition", "content": "Translation de vecteur u : chaque point glisse de la même flèche. L'image de A est A' tel que $\\overrightarrow{AA'}$ = $\\vec{u}$. La figure ne change ni de forme ni de taille.", "titre": "Translation"}, {"id": 4, "type": "theoreme", "content": "ABCD est un parallélogramme si et seulement si $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$. On lit les lettres dans l'ordre du tour.", "titre": "Parallélogramme"}, {"id": 5, "type": "theoreme", "content": "$\\overrightarrow{AB}$ + $\\overrightarrow{BC}$ = $\\overrightarrow{AC}$. On enchaîne les flèches, la lettre du milieu disparaît.", "titre": "Relation de Chasles"}, {"id": 6, "type": "definition", "content": "$\\overrightarrow{AB}$ a pour coordonnées (x_B − x_A ; y_B − y_A). Toujours arrivée moins départ.", "titre": "Coordonnées"}, {"id": 7, "type": "methode", "content": "Pour additionner deux vecteurs, on additionne leurs coordonnées une à une. Pour multiplier un vecteur par un nombre, on multiplie chacune de ses coordonnées par ce nombre.", "titre": "Somme et multiple"}, {"id": 8, "type": "definition", "content": "La norme de $\\overrightarrow{AB}$, notée ‖$\\overrightarrow{AB}$‖, vaut $\\sqrt{x^2+y^2}$ où (x ; y) sont les coordonnées de $\\overrightarrow{AB}$. C'est aussi la distance AB.", "titre": "Norme"}, {"id": 9, "type": "definition", "content": "Les coordonnées du milieu d'un segment sont les moyennes de celles des deux extrémités.", "titre": "Milieu"}, {"id": 10, "type": "exemple", "content": "A(1 ; 2) et B(4 ; 6). $\\overrightarrow{AB}$ (4 − 1 ; 6 − 2) = (3 ; 4). Norme : √(3² + 4²) = √25 = 5. Milieu de [AB] : ((1+4)/2 ; (2+6)/2) = (2,5 ; 4).", "titre": "Exemple résolu"}, {"id": 11, "type": "remarque", "content": "Lire les lettres dans le mauvais ordre : pour ABCD, c'est $\\overrightarrow{AB}$ = $\\overrightarrow{DC}$, pas $\\overrightarrow{AB}$ = $\\overrightarrow{CD}$.\nFaire départ moins arrivée au lieu d'arrivée moins départ : la coordonnée change de signe.\nOublier les parenthèses avec un négatif : 5 − (−2) = 7, pas 3.", "titre": "Pièges classiques"}, {"id": 12, "type": "remarque", "content": "La flèche se note toujours au-dessus des lettres : $\\overrightarrow{AB}$, jamais AB tout court. C'est sanctionné si elle manque.", "titre": "Pour le contrôle"}, {"id": 13, "type": "exemple", "content": "La colinéarité (deux vecteurs colinéaires si l'un est un multiple de l'autre), le déterminant pour la tester, puis les équations de droites. À confirmer avec le cahier qu'il n'y en a pas au prochain contrôle.", "titre": "Ce qui vient après (pas pour cette interro)"}]$coursJson4$
WHERE niveau = '2nde' AND chapitre = 'Vecteurs dans le plan';

-- Verification : la colonne ne doit plus contenir "→" suivi d'une lettre.
-- SELECT id, contenu FROM cours WHERE niveau = '2nde' AND chapitre = 'Vecteurs dans le plan';
